// Convert Polygon2d to vector of points for CGAL boolean operations
std::vector<cg3::Point2d> poly1Points;
std::vector<cg3::Point2d> poly2Points;

for (unsigned int i = 0; i < P1.size(); ++i) {
    poly1Points.push_back(P1[i]);
}
for (unsigned int i = 0; i < P2.size(); ++i) {
    poly2Points.push_back(P2[i]);
}

// Use CGAL boolean intersection
std::vector<std::vector<cg3::Point2d>> result = cg3::cgal::intersection(poly1Points, poly2Points);

// Convert result to PolygonWithHoles2d format
std::vector<PolygonWithHoles2d> output;
for (const auto& polygon : result) {
    PolygonWithHoles2d pwh;
    Polygon2d outer;
    for (const auto& point : polygon) {
        outer.pushBack(point);
    }
    pwh.setOuter(outer);
    output.push_back(pwh);
}

return output;
